39	        this.result = null;
40	        this.thrown = null;
41	    }
42	
43	    @Given("회원 {long}이 등록되어 있다")
44	    public void 회원이_등록되어_있다(long userId) {
45	        userStore.seed(new UserRecord(userId, "user-" + userId));
46	    }
47	
